const body = $json.body || $json;

const isAuthenticated = !!(body.user_context && body.user_context.is_authenticated);
const authToken = body.auth_token || '';
const userMessage = body.message;
const sessionId = body.session_id || 'unknown';

const systemPrompt = `Tu es l'agent de mise en relation de Darimmo, une plateforme marocaine d'annonces immobilieres.

Ton role : aider un utilisateur AUTHENTIFIE a preparer un message vers le proprietaire d'une annonce.

Regles strictes :
- Si l'annonce concernee n'est pas clairement identifiee (pas d'ID ni de titre reconnaissable dans le message ou l'historique), pose UNE question pour demander de preciser laquelle AVANT d'appeler l'outil.
- Tu peux aider l'utilisateur a reformuler son message pour qu'il soit poli et clair, mais n'invente JAMAIS de contenu factuel (numero de telephone, disponibilite, prix negocie) que l'utilisateur n'a pas donne lui-meme.
- Reponds TOUJOURS dans la meme langue que le message de l'utilisateur. Si l'utilisateur ecrit en darija (arabe marocain, en caracteres latins ou arabes), en arabe standard, en francais ou en anglais, reponds dans cette meme langue.`;

const tools = [
  {
    name: "prepare_contact_request",
    description: "Envoie une demande de contact au proprietaire d'une annonce precise, de la part de l'utilisateur connecte.",
    parameters: {
      type: "OBJECT",
      properties: {
        annonce_id: { type: "NUMBER" },
        message: { type: "STRING" }
      },
      required: ["annonce_id", "message"]
    }
  }
];

return {
  json: {
    is_authenticated: isAuthenticated,
    auth_token: authToken,
    original_user_message: userMessage,
    session_id: sessionId,
    gemini_request_body: {
      contents: [{ role: "user", parts: [{ text: `${systemPrompt}\n\nMessage de l'utilisateur : "${userMessage}"` }] }],
      tools: [{ functionDeclarations: tools }]
    }
  }
};

return {
  json: {
    reply: "Vous devez etre connecte pour contacter un proprietaire. Merci de vous connecter puis de reessayer.",
    session_id: $json.session_id,
    recommended_annonce_ids: [],
    intent: "contact_owner",
    metadata: { agent_used: "communication_agent", tool_calls_count: 0, llm_calls_count: 0 }
  }
};

const prevData = $('Build Prompt And Tools').item.json;
const candidate = $json.candidates[0];
const parts = candidate.content.parts;
const functionCallPart = parts.find(p => p.functionCall);

if (!functionCallPart) {
  const textPart = parts.find(p => p.text);
  return {
    json: {
      needs_tool_call: false,
      direct_reply: textPart ? textPart.text : "Je n'ai pas compris votre demande.",
      session_id: prevData.session_id
    }
  };
}

const toolName = functionCallPart.functionCall.name;
const args = functionCallPart.functionCall.args;
const authToken = prevData.auth_token;

return {
  json: {
    needs_tool_call: true,
    tool_name: toolName,
    tool_args: args,
    auth_token: authToken,
    original_user_message: prevData.original_user_message,
    session_id: prevData.session_id
  }
};

return {
  json: {
    reply: $json.direct_reply,
    session_id: $json.session_id,
    recommended_annonce_ids: [],
    intent: "contact_owner",
    metadata: { agent_used: "communication_agent", tool_calls_count: 0, llm_calls_count: 1 }
  }
};

// Ce noeud enrichit le message de l'utilisateur avec le titre de
// l'annonce et un lien direct, AVANT de l'envoyer au proprietaire,
// pour que le destinataire sache tout de suite de quelle annonce il s'agit.
const prevData = $('Extraire functionCall et preparer requete Django').item.json;
const annonceDetails = $json; // resultat de "Recuperer details annonce"

// Adapter ce chemin a la vraie route du frontend si elle differe.
const FRONTEND_URL = 'http://localhost:5173';
const annonceLink = `${FRONTEND_URL}/annonces/${annonceDetails.id}`;

const originalMessage = prevData.tool_args.message;

const enrichedMessage = `${originalMessage}\n\n--\nConcernant l'annonce : "${annonceDetails.title}" (${annonceDetails.city})\nLien : ${annonceLink}`;

return {
  json: {
    tool_name: prevData.tool_name,
    django_method: 'POST',
    django_url: 'http://127.0.0.1:8000/api/messaging/conversations/contacter/',
    django_body: { annonce: annonceDetails.id, message: enrichedMessage },
    auth_token: prevData.auth_token,
    annonce_title: annonceDetails.title,
    annonce_city: annonceDetails.city,
    annonce_id: annonceDetails.id,
    annonce_link: annonceLink,
    original_user_message: prevData.original_user_message,
    session_id: prevData.session_id
  }
};

const prevData = $('Enrichir message avec titre et lien').item.json;
const contactResult = $json; // resultat de "Appel reel API Django"

return {
  json: {
    tool_name: prevData.tool_name,
    tool_result: {
      ...contactResult,
      annonce_title: prevData.annonce_title,
      annonce_city: prevData.annonce_city,
      annonce_id: prevData.annonce_id,
      annonce_link: prevData.annonce_link
    },
    original_user_message: prevData.original_user_message,
    session_id: prevData.session_id
  }
};

const d = $json;

const prompt = `Tu es l'agent de mise en relation de Darimmo.

Outil appele : ${d.tool_name}
Resultat retourne par l'API (inclut le titre, la ville et le lien de l'annonce concernee) : ${JSON.stringify(d.tool_result)}

Message original de l'utilisateur : "${d.original_user_message}"

Regles strictes :
- Base ta reponse UNIQUEMENT sur le resultat fourni ci-dessus. N'invente rien.
- Si le resultat contient une erreur (ex: 403, 404), explique clairement que l'annonce n'est pas accessible ou n'existe pas, sans detailler la cause technique.
- Si l'envoi a reussi, confirme-le clairement en mentionnant le TITRE de l'annonce et sa ville (pas seulement son numero). Tu peux aussi rappeler que le message envoye au proprietaire inclut deja le lien de l'annonce.
- Reponds TOUJOURS dans la meme langue que le message de l'utilisateur. Si l'utilisateur ecrit en darija (arabe marocain, en caracteres latins ou arabes), en arabe standard, en francais ou en anglais, reponds dans cette meme langue.`;

return {
  json: {
    gemini_request_body: { contents: [{ role: "user", parts: [{ text: prompt }] }] },
    session_id: d.session_id,
    annonce_id: d.tool_result.annonce_id
  }
};

const replyText = $json.candidates[0].content.parts[0].text;
const prevData = $('Construire prompt final').item.json;

return {
  json: {
    reply: replyText,
    session_id: prevData.session_id,
    recommended_annonce_ids: [prevData.annonce_id],
    intent: "contact_owner",
    metadata: { agent_used: "communication_agent", tool_calls_count: 1, llm_calls_count: 2 }
  }
};
